"use client";

import * as React from "react";
import { CalendarCheck, Clock } from "lucide-react";
import { DataTable, type Column } from "@/components/ui/DataTable";
import { StatusBadge } from "@/components/ui/StatusBadge";
import { formatCents } from "@/lib/format";
import { t } from "@/lib/i18n";

export interface PayoutRowData {
  id: string;
  periodLabel: string;
  periodEndMs: number;
  amountCents: number;
  status: "scheduled" | "paid";
}

export function PayoutsTable({ rows }: { rows: PayoutRowData[] }) {
  const columns: Column<PayoutRowData>[] = [
    {
      key: "periodLabel",
      header: t("provider.colPeriod"),
      sortable: true,
      sortValue: (r) => r.periodEndMs,
    },
    {
      key: "amountCents",
      header: t("provider.colAmount"),
      align: "right",
      sortable: true,
      sortValue: (r) => r.amountCents,
      render: (r) => formatCents(r.amountCents),
    },
    {
      key: "status",
      header: t("provider.colStatus"),
      render: (r) =>
        r.status === "paid" ? (
          <StatusBadge tone="success" icon={CalendarCheck}>
            {t("provider.payoutPaid")}
          </StatusBadge>
        ) : (
          <StatusBadge tone="warning" icon={Clock}>
            {t("provider.payoutScheduled")}
          </StatusBadge>
        ),
    },
  ];

  return (
    <DataTable
      caption={t("provider.payoutHistoryCaption")}
      columns={columns}
      rows={rows}
      getRowKey={(r) => r.id}
      emptyText={t("provider.payoutsNone")}
    />
  );
}
